def validate_bundle(bundle, asset_root=None):
    """Select the explicit namespace; C01 validation and defaults stay unchanged."""
    version = bundle.get('format_version') if isinstance(bundle, dict) else getattr(bundle, 'format_version', None)
    if version == RECOVERY_EXCHANGE_VERSION:
        return validate_recovery_bundle(bundle, asset_root=asset_root)
    return _legacy_validate_bundle(bundle, asset_root=asset_root)

def assert_plan_ready(bundle, plan_ref, current_snapshot_ref):
    version = bundle.get('format_version') if isinstance(bundle, dict) else getattr(bundle, 'format_version', None)
    if version == RECOVERY_EXCHANGE_VERSION:
        return assert_recovery_plan_ready(bundle, plan_ref, current_snapshot_ref)
    return _legacy_assert_plan_ready(bundle, plan_ref, current_snapshot_ref)

def seal_artifact(data):
    version = data.get('schema_version') if isinstance(data, dict) else getattr(data, 'schema_version', None)
    if version == RECOVERY_SCHEMA_VERSION:
        return seal_recovery_artifact(data)
    return _legacy_seal_artifact(data)

def validate_bundle(bundle, asset_root=None):
    """Validate schema, exact dependencies, geometry, policy and state invariants.

    asset_root=None deliberately skips file-byte validation; load_bundle defaults to it on.
    Re-parse even model instances to catch mutations of nested Python lists/dicts.
    """
    try:
        bundle = ExchangeBundle.model_validate(as_data(bundle))
    except ValidationError as error:
        raise ContractError([{"path": "$" + "".join("[{}]".format(x) if isinstance(x, int) else "." + x for x in e["loc"]),
                              "code": "SCHEMA", "message": e["msg"]} for e in error.errors(include_url=False)]) from error
    ctx = _Context(bundle)
    _relationships(ctx)
    _resources(ctx, asset_root)
    handlers = {"SourceBundle": _source, "EvidenceBundle": _evidence, "QuestionGraph": _graph,
                "CheckReport": _check, "ApplyPlan": _plan, "ExecutionReceipt": _receipt,
                "ReviewPatch": _patch, "BatchReport": _batch}
    all_issues = {issue.issue_id for a in bundle.artifacts if a.kind == "CheckReport" for issue in a.payload.issues}
    for key, artifact in ctx.artifacts.items():
        path = ctx.paths[key] + ".payload"
        if artifact.kind in handlers:
            handlers[artifact.kind](ctx, artifact, path)
        if artifact.kind == "PlatformSnapshot":
            p = artifact.payload
            distinct(p.directories, path + ".directories")
            distinct([c.name for c in p.capabilities], path + ".capabilities")
            distinct([q.platform_question_id for q in p.questions], path + ".questions")
            distinct([f.platform_frame_id for f in p.frames], path + ".frames")
            for i, question in enumerate(p.questions):
                if question.directory_id not in p.directories:
                    fail(path + ".questions[{}].directory_id".format(i), "MISSING_REFERENCE", "platform question directory is absent from this snapshot")
            for i, cap in enumerate(p.capabilities):
                ctx.evrefs(cap.evidence_refs, path + ".capabilities[{}].evidence_refs".format(i))
            ctx.evrefs(p.evidence_refs, path + ".evidence_refs")
            for i, frame in enumerate(p.frames):
                subset([frame.platform_question_id], {q.platform_question_id for q in p.questions}, path + ".frames[{}]".format(i))
        for name in ("unresolved_issue_ids", "related_issue_ids"):
            if hasattr(artifact.payload, name):
                subset(getattr(artifact.payload, name), all_issues, path + "." + name)
        if artifact.producer.evidence_mode == "OBSERVED":
            # A synthetic evidence file cannot be relabeled into an observation chain.
            for location, value in walk(artifact, ctx.paths[key]):
                if isinstance(value, list) and location.endswith("evidence_refs"):
                    for evidence_id in value:
                        if evidence_id in ctx.evidence and ctx.evidence[evidence_id].mode == "SYNTHETIC":
                            fail(location, "SYNTHETIC_EVIDENCE", "observed artifact references synthetic evidence")
    return bundle

def validate_recovery_bundle(bundle, *, asset_root=None, _archive=False):
    root = asset_root if asset_root is not None else getattr(bundle, 'asset_root', None)
    data = _data(bundle)
    if not isinstance(data, dict) or data.get('format_version') != RECOVERY_EXCHANGE_VERSION:
        fail('$', 'RECOVERY_VERSION_UNSUPPORTED', 'expected approved recovery exchange namespace')
    if any(a.get('schema_version') != RECOVERY_SCHEMA_VERSION for a in data.get('artifacts', [])):
        fail('$', 'CROSS_VERSION_REFERENCE', 'one recovery namespace required')
    FrozenSchemas().check(data)
    if root is None:
        fail('$', 'RESOURCE_ROOT_REQUIRED', 'recovery validation never skips actual resource bytes')
    ctx = _Closure(data, root, synthetic=not _archive)
    ctx.check()
    for a in data['artifacts']:
        _timestamp(a['created_at'])
    if not _archive:
        _scope(ctx)
    _intents(ctx)
    heads = _resolutions(ctx)
    _receipts_progress(ctx, heads)
    _legacy_projection(ctx)
    _reports(ctx, heads)
    return RecoveryExchangeBundle(data, root)

def verify_generated_plan(bundle, plan, current_ref, config, *, observation_binding=None):
    """Recompute supported projection/facts before mock dispatch; refuse edited actions."""
    bundle = validate_bundle(bundle)
    payload = plan.payload
    if observation_binding is not None:
        binding = _plain(observation_binding)
        if plan.schema_version != "1.1.0-a-recovery-proposal":
            reject("RECOVERY_VERSION_UNSUPPORTED", "observation bridge is recovery-version only")
        if (binding.get("plan_ref") != artifact_ref(plan) or
                binding.get("before_snapshot_ref") != _plain(payload.snapshot) or
                binding.get("observed_snapshot_ref") != _plain(current_ref)):
            reject("OBSERVATION_BINDING_MISMATCH", "fresh observation bridge does not bind exact plan/current refs")
        current_ref = payload.snapshot
    if plan.producer.config_version != config.version:
        reject("AUTHORIZATION_CHANGED", "current authorization/config differs from planned version")
    # Rebuild without this plan or its descendants; retain upstream history so UNKNOWN stays visible.
    data = bundle.model_dump(mode="json")
    remove = {(plan.artifact_id, plan.revision)}
    while True:
        previous_count = len(remove)
        for item in data["artifacts"]:
            if any((r["artifact_id"], r["revision"]) in remove for r in item["input_refs"]):
                remove.add((item["artifact_id"], item["revision"]))
        if len(remove) == previous_count:
            break
    data["artifacts"] = [a for a in data["artifacts"] if (a["artifact_id"], a["revision"]) not in remove]
    if plan.schema_version == "1.1.0-a-recovery-proposal":
        # This is an internal historical derivation, after validating the full
        # package above. Runtime result evidence that is not consumed by any
        # retained upstream Artifact must not refer back into the intentionally
        # removed plan/descendants. Retain the complete formal evidence closure
        # of every retained Artifact; never filter history in the admitted
        # bundle, return this view, or use it as current write eligibility.
        from pathlib import Path
        records = {record["evidence_id"]: record for record in data["evidence"]}
        needed, seen_resources = set(), set()
        root = Path(bundle.asset_root)
        evidence_fields = {"evidence_refs", "before_evidence_refs", "after_evidence_refs", "submission_evidence_refs"}

        def consume_evidence(evidence_id):
            if evidence_id in needed:
                return
            if evidence_id not in records:
                reject("MISSING_REFERENCE", "upstream formal evidence ID is absent")
            needed.add(evidence_id)
            consume(records[evidence_id]["resource"])

        def consume(value):
            if isinstance(value, list):
                for member in value:
                    consume(member)
            elif isinstance(value, dict):
                if {"path", "sha256", "media_type"}.issubset(value):
                    key = (value["path"], value["sha256"], value["media_type"])
                    if key not in seen_resources and value["media_type"] == "application/json":
                        seen_resources.add(key)
                        # Full validation already checked safe paths, bytes,
                        # all ordinary refs and mixed-resource cycle freedom.
                        consume(json.loads((root / value["path"]).read_text(encoding="utf-8")))
                else:
                    for name, child in value.items():
                        if name in evidence_fields and isinstance(child, list):
                            for member in child:
                                if isinstance(member, str):
                                    consume_evidence(member)
                        consume(child)

        for upstream_artifact in data["artifacts"]:
            consume(upstream_artifact)
        data["evidence"] = [record for record in data["evidence"] if record["evidence_id"] in needed]
    upstream = validate_bundle(data, asset_root=getattr(bundle, "asset_root", None))
    generated = create_plan(upstream, payload.graph, payload.precheck, payload.targetcheck,
                            payload.snapshot, current_ref, payload.policy, config,
                            artifact_id=plan.artifact_id, created_at=plan.created_at, run_id=plan.run_id)
    rebuilt = generated.artifacts[-1]
    if rebuilt != plan:
        reject("PLAN_CHANGED", "plan does not equal generated supported projection")

def snapshot_state_equivalent(planned_snapshot, observed_snapshot, *, planned_target_state, observed_target_state):
    from annotation.contracts import target_state_digest
    planned, observed = _plain(planned_snapshot), _plain(observed_snapshot)
    old, new = _plain(planned_target_state), _plain(observed_target_state)
    if planned["schema_version"] != "1.1.0-a-recovery-proposal" or observed["schema_version"] != planned["schema_version"]:
        reject("RECOVERY_VERSION_UNSUPPORTED", "state bridge is limited to recovery contracts")
    for name in ("target_key", "source_ref", "scope_id", "target_session_id"):
        if old.get(name) != new.get(name) or name not in old:
            reject("OBSERVATION_BINDING_MISMATCH", "state bridge fixed identity differs: " + name)
    hashes = (target_state_digest(old), target_state_digest(new))
    if hashes != (planned["payload"]["observed_hash"], observed["payload"]["observed_hash"]):
        reject("OBSERVATION_BINDING_MISMATCH", "snapshot digest does not bind the actual compared business state")
    versions = (planned["payload"]["observed_version"], observed["payload"]["observed_version"])
    equivalent = hashes[0] == hashes[1] and versions[0] == versions[1]
    return PublicRecord(equivalent=equivalent, planned_snapshot_ref=artifact_ref(planned),
                        observed_snapshot_ref=artifact_ref(observed), planned_state_hash=hashes[0],
                        observed_state_hash=hashes[1], planned_state_version=versions[0], observed_state_version=versions[1],
                        reasons=["business state matches" if equivalent else "business state changed"])

def open(cls, target_dir, *, expected_store_id, expected_target_session_id,
             expected_target_key, expected_scope_id, expected_source_ref):
        directory = Path(target_dir).resolve()
        path = directory / "target.sqlite3"
        if not path.is_file():
            reject("TARGET_STORE_MISSING", "reopen never initializes a missing target store")
        try:
            with sqlite3.connect(path.as_uri() + "?mode=rw", uri=True, timeout=1.0, factory=_ClosingConnection) as db:
                if db.execute("PRAGMA application_id").fetchone()[0] != APPLICATION_ID or db.execute("PRAGMA user_version").fetchone()[0] != 1:
                    reject("TARGET_STORE_VERSION_UNSUPPORTED", "target application or user version differs")
                if db.execute("PRAGMA quick_check").fetchone()[0] != "ok":
                    reject("TARGET_STORE_CORRUPT", "target integrity check failed")
                row = db.execute("SELECT value FROM meta WHERE key='descriptor'").fetchone()
                descriptor = json.loads(row[0])
                json.loads(db.execute("SELECT value FROM meta WHERE key='state'").fetchone()[0])
        except (sqlite3.Error, ValueError, TypeError, KeyError) as exc:
            reject("TARGET_STORE_CORRUPT", str(exc))
        if descriptor.get("directory") != str(directory):
            reject("STATE_DIRECTORY_IDENTITY_MISMATCH", "target directory differs from established identity")
        if descriptor.get("format") != FORMAT:
            reject("TARGET_STORE_VERSION_UNSUPPORTED", "target format differs")
        if descriptor.get("store_id") != expected_store_id or descriptor.get("target_key") != _plain(expected_target_key):
            reject("TARGET_IDENTITY_MISMATCH", "target store/key differs")
        if descriptor.get("target_session_id") != expected_target_session_id:
            reject("TARGET_SESSION_BINDING_MISMATCH", "target session differs")
        if descriptor.get("fixed_scope_id") != expected_scope_id:
            reject("TARGET_SCOPE_SWITCH_UNSUPPORTED", "fixed session scope cannot change")
        if descriptor.get("fixed_source_ref") != _plain(expected_source_ref):
            reject("SOURCE_BINDING", "fixed session source revision/hash cannot change")
        return cls(directory, descriptor)

def _verify_observation(self, observation):
        value = _plain(observation)
        with self._connect() as db:
            row = db.execute("SELECT body FROM observations WHERE observation_id=?", (value.get("observation_id"),)).fetchone()
        if row is None:
            reject("OBSERVATION_MISSING", "actual persisted observation does not exist")
        original = json.loads(row[0])
        resource = value.get("resource", value.get("readback"))
        if resource is None:
            reject("RESOURCE_MISSING", "observation resource is missing")
        path = (self.asset_root / resource["path"]).resolve()
        if not path.is_relative_to(self.asset_root) or not path.is_file() or path.is_symlink():
            reject("RESOURCE_MISSING", "observation resource path is missing or outside its root")
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != resource["sha256"]:
            reject("RESOURCE_HASH_MISMATCH", "observation bytes differ from their resource digest")
        if json.loads(raw) != original:
            reject("OBSERVATION_BINDING_MISMATCH", "observation resource differs from independent persisted read")
        for name, member in original.items():
            if value.get(name) != member:
                reject("OBSERVATION_BINDING_MISMATCH", "observation differs from actual persisted target read")
        if original["read_status"] != "OK" or not original["relevant_scope_completeness"]:
            reject("READBACK_INCOMPLETE", "snapshot requires complete actual target read")
        return original
